import attr
from attr.validators import deep_iterable, deep_mapping, instance_of, min_len
c = attr.make_class('C', {'a': attr.ib(validator=deep_iterable([instance_of(int)], [instance_of(list), min_len(1)]))})
try:
    c(a=[1,2])
except Exception as e:
    print('deep_iterable list ->', type(e).__name__, e)
